    // Gate 98: HRR-Bra [HRR-Bra: I(0,3)|3,0 from I(1,2|3,0) + AB*I(0,2|3,0) [m=3]]
    operands[99] = 1.0 * operands[95] + prefactors[5] * operands[94];
    // Gate 99: HRR-Bra [HRR-Bra: I(1,3)|3,0 from I(2,2|3,0) + AB*I(1,2|3,0) [m=3]]
    operands[100] = 1.0 * operands[96] + prefactors[5] * operands[95];
    // Gate 100: HRR-Bra [HRR-Bra: I(2,3)|3,0 from I(3,2|3,0) + AB*I(2,2|3,0) [m=3]]
    operands[101] = 1.0 * operands[97] + prefactors[5] * operands[96];
    // Gate 101: HRR-Bra [HRR-Bra: I(3,3)|3,0 from I(4,2|3,0) + AB*I(3,2|3,0) [m=3]]
    operands[102] = 1.0 * operands[98] + prefactors[5] * operands[97];
    // Gate 102: HRR-Ket [HRR-Ket: I(3,3)|0,1) from I(3,3)|1,0) + CD*I(3,3)|0,0)]
    operands[103] = 1.0 * operands[72] + prefactors[6] * operands[57];
    // Gate 103: HRR-Ket [HRR-Ket: I(3,3)|1,1) from I(3,3)|2,0) + CD*I(3,3)|1,0)]
    operands[104] = 1.0 * operands[87] + prefactors[6] * operands[72];
    // Gate 104: HRR-Ket [HRR-Ket: I(3,3)|2,1) from I(3,3)|3,0) + CD*I(3,3)|2,0)]
    operands[105] = 1.0 * operands[102] + prefactors[6] * operands[87];
